"""Expandable industrial, societal and geographic inquiry with provenance."""
import time,threading,copy
DOMAINS={
 'industry':['Electricity generation','Transmission and storage','Water and sanitation','Agriculture and food processing','Mining and minerals','Metals and metallurgy','Polymers and chemicals','Manufacturing and machining','Automation and robotics','Construction and housing','Transport and logistics','Telecommunications','Computing and semiconductors','Healthcare supply chains','Repair and maintenance','Waste and circular production','Industrial safety','Resource allocation and transition'],
 'society':['Individual dignity and development','Family and household structures','Parenting and child welfare','Elders and intergenerational care','Disability and accessibility','Kinship and community networks','Language and oral traditions','Arts and living heritage','Religion and spiritual practice','Education and knowledge transmission','Work and unpaid care','Migration and displacement','Governance and public institutions','Justice and accountability','Inequality and exclusion','Conflict and cooperation','Rural and urban communities','Cultural change and historical context'],
 'geography':['Continents and regions','Countries and administrative boundaries','Population and settlement','Physical terrain and elevation','Rivers watersheds and freshwater','Oceans coasts and islands','Climate zones and weather','Biomes and ecosystems','Soils and agriculture','Mineral and energy resources','Transport and accessibility','Cities and infrastructure','Natural hazards and resilience','Migration and demographic change','Land use and ecological pressures','Remote communities and service access','Map projections scale and uncertainty','Geographic data provenance and dates']}
SOURCES={
 'industry':[('UNIDO cleaner production','https://www.unido.org/cross-cutting-priorities/cleaner-production-and-circular-economy','Resource efficiency, safer substances and circular production.'),('IEA technology perspectives','https://www.iea.org/reports/Energy-Technology-Perspectives-2024','Energy technology deployment, manufacturing and supply-chain analysis.'),('Fuller design science','https://www.bfi.org/about-fuller/big-ideas/design-science/design-science-primer/','Whole-system anticipatory design perspective.'),('Fresco resource-based economy','https://www.thevenusproject.com/faq/what-is-a-resource-based-economy/','Proposed resource-based provision model; evaluate transition and delivery separately.')],
 'society':[('UNESCO living heritage','https://ich.unesco.org/en/what-is-intangible-heritage-00003','Community-recognised practices, knowledge and cultural transmission.'),('UNICEF parenting support','https://www.unicef.org/support-parenting','Caregiver support and enabling environments for child development.'),('UN DESA social inclusion','https://www.un.org/development/desa/en/key-issues/social','Poverty, inequality, age, disability, families and inclusion.')],
 'geography':[('Natural Earth','https://www.naturalearthdata.com/','Public-domain cartographic datasets; map scale affects interpretation.'),('World Bank data','https://data.worldbank.org/','Country and development indicators; retain indicator definitions and dates.'),('NASA Earthdata','https://www.earthdata.nasa.gov/','Earth-observation data discovery; access and product coverage vary.')]}
FOUR=[('True good','Provision, dignity, fair work, resilient services and ecological protection.'),('False good','Growth, output or efficiency presented as success while harm is concealed.'),('False evil','Useful cooperation, repair or essential provision wrongly condemned because it reduces profit or challenges a convention.'),('True evil','Exploitation, coercion, deception and avoidable suffering sustained for advantage.')]
class WorldKnowledge:
 def __init__(self):self.research=None;self.intake=None;self.next_at=0;self.sequence=0;self.latest={};self.lock=threading.RLock()
 def view(self,kind):
  if kind not in DOMAINS:raise ValueError('Unknown knowledge domain')
  reports=[]
  if self.intake:
   for topic in DOMAINS[kind][:3]:
    try:reports.extend(x for x in self.intake.retrieve(topic) if not x.get('private'))
    except Exception:pass
  return {'kind':kind,'topics':DOMAINS[kind],'sources':[{'title':a,'url':b,'summary':d} for a,b,d in SOURCES[kind]],'four_way':[{'category':a,'test':b} for a,b in FOUR],'sequence':self.sequence,'latest':copy.deepcopy(self.latest),'reports':list({x.get('url',x.get('title','')):x for x in reports}.values())[:12],'principle':'Souls over digits: knowledge and infrastructure serve living beings, essential provision and dignity.','lenses':{'Tesla':'Electrical and energy-system inquiry: track power, conversion, losses and measured performance; do not infer unlimited energy from aspiration.','Fresco':'Study resource inventory, access, automation and proposed provision beyond money-first priorities.','Fuller':'Study whole systems, resource efficiency and consequences across time and scale.','society':'Use local and community accounts; no single family form or national average describes everyone.','geography':'Retain place, scale, date, resolution and uncertainty. Public regional data does not identify private households.'},'scope':'Foundational topic catalogue and indexed source notes with rotating public research requests; not a complete ingestion of world knowledge.'}
 def tick(self,c):
  if time.monotonic()<self.next_at:return
  self.next_at=time.monotonic()+900
  kinds=list(DOMAINS);kind=kinds[self.sequence%3];topic=DOMAINS[kind][(self.sequence//3)%len(DOMAINS[kind])];status='No research provider attached'
  if self.research:
   try:self.research.request(topic+' welfare resources evidence');status='Public research request submitted; retrieval status belongs to research library'
   except Exception as e:status=type(e).__name__+': '+str(e)[:150]
  self.sequence+=1;self.latest={'domain':kind,'topic':topic,'status':status,'assessment_questions':['Who benefits and who bears costs?','What follows from action, inaction and alternatives?','Which human and ecological dependencies must remain intact?','What source, date, local context and outcome checks support the conclusion?']}
  c.bus.publish({'origin':'world-knowledge','target':'all','kind':'stage-output','payload':{'sequence':self.sequence,'topic_index':(self.sequence//3),'provenance':'public-knowledge-discovery-request','stochastic':False,'predefined_text':True}})
